import React from 'react';
import { Link } from 'react-router-dom';
import { motion } from 'framer-motion';

import ISText from './assets/IronpulseText.png';

import FBIcon from './assets/AstroAssault.png';
import PFantom from './assets/ProjectPhantom.png';
import PFAlien from './assets/ProjectFallaceAlien.png';
import BTreas from './assets/BrowserTreasure.png';
import PBS from './assets/ProjectBreakerScreen1.png';

/* ================= GAME DATA ================= */
const genreSections = [
  {
    title: 'FEATURED',
    games: [
      {
        name: 'PROJECT BREAKER',
        image: PBS,
        release: '2026',
      },
      {
        name: 'PROJECT PHANTOM',
        image: PFantom,
        release: '2027',
      },
      {
        name: 'PROJECT FALLACE',
        image: PFAlien,
        release: '2028',
      },
    ],
  },
  {
    title: 'SCI-FI',
    games: [
      {
        name: 'PROJECT BREAKER',
        image: FBIcon,
        release: '2026',
      },
      {
        name: 'PROJECT FALLACE',
        image: PFAlien,
        release: '2028',
      },
    ],
  },
  {
    title: 'HORROR',
    games: [
      {
        name: 'PROJECT PHANTOM',
        image: PFantom,
        release: '2027',
      },
      {
        name: 'PROJECT FALLACE',
        image: PFAlien,
        release: '2028',
      },
    ],
  },
  {
    title: 'BROWSER GAMES',
    games: [
      {
        name: 'BROWSER TREASURE',
        image: BTreas,
        release: '2025',
      },
    ],
  },
];

/* ================= GAME CARD ================= */
function GameCard({ game }) {
  return (
    <motion.div
      whileHover={{ scale: 1.04, y: -5 }}
      transition={{ duration: 0.25 }}
      className="min-w-[320px] h-[420px] relative rounded-2xl overflow-hidden border border-cyan-500/10 bg-gray-950 shadow-[0_0_30px_rgba(34,211,238,0.08)] group"
    >
      <img
        src={game.image}
        alt={game.name}
        className="w-full h-full object-cover group-hover:scale-105 transition duration-500"
      />

      <div className="absolute inset-0 bg-gradient-to-t from-black via-black/50 to-transparent" />

      <div className="absolute bottom-0 left-0 p-6 w-full">
        <p className="text-xs tracking-[0.25em] text-cyan-300 mb-2">
          RELEASE • {game.release}
        </p>

        <h3 className="text-2xl font-bold tracking-wide text-white mb-4">
          {game.name}
        </h3>

        <button className="px-5 py-2 bg-cyan-600 hover:bg-cyan-500 rounded-md text-sm font-semibold shadow-[0_0_20px_rgba(34,211,238,0.25)] transition">
          VIEW GAME
        </button>
      </div>
    </motion.div>
  );
}

/* ================= GENRE ROW ================= */
function GenreRow({ title, games }) {
  return (
    <section className="mb-24">
      <div className="flex items-center justify-between mb-8">
        <h2 className="text-3xl md:text-4xl font-bold tracking-[0.2em] text-cyan-300">
          {title}
        </h2>

        <button className="text-sm tracking-widest text-gray-400 hover:text-cyan-300 transition">
          VIEW ALL
        </button>
      </div>

      <div className="overflow-x-auto scrollbar-hide">
        <div className="flex gap-8 pb-4 min-w-max">
          {games.map((game, index) => (
            <GameCard key={index} game={game} />
          ))}
        </div>
      </div>
    </section>
  );
}

